def seed_products(apps, schema_editor):
    """Attach categories and kilogram weights without reinterpreting posted quantities.

    Existing flour stays in kilograms. A bag product is a new unit, not a rewrite of
    historical kilogram movements. Stock rows snapshot the unit that was actually posted.
    """

    ProductCategory = apps.get_model("inventory", "ProductCategory")
    UnitOfMeasure = apps.get_model("inventory", "UnitOfMeasure")
    Product = apps.get_model("inventory", "Product")
    StockMove = apps.get_model("inventory", "StockMove")
    Warehouse = apps.get_model("inventory", "Warehouse")
    StorageLocation = apps.get_model("inventory", "StorageLocation")
    from apps.inventory.reference_data import CATEGORIES, UNITS

    for code, name in UNITS:
        UnitOfMeasure.objects.update_or_create(code=code, defaults={"name": name, "active": True})
    for code, name, role, description in CATEGORIES:
        ProductCategory.objects.update_or_create(
            code=code,
            defaults={"name": name, "role": role, "description": description, "active": True},
        )
    categories = {row.code: row.pk for row in ProductCategory.objects.all()}
    for product in Product.objects.all().iterator():
        weight = Decimal("1.000") if product.unit == "KG" else None
        Product.objects.filter(pk=product.pk).update(
            category_id=categories.get(product.kind),
            unit_weight_kg=weight,
        )
        StockMove.objects.filter(product_id=product.pk).update(unit_code=product.unit, unit_weight_kg=weight)
    for warehouse in Warehouse.objects.all().iterator():
        location = StorageLocation.objects.filter(warehouse_id=warehouse.pk, name="Основное").first()
        if location is None:
            StorageLocation.objects.create(warehouse_id=warehouse.pk, name="Основное", active=True)
        elif not location.active:
            StorageLocation.objects.filter(pk=location.pk).update(active=True)


